contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint newMinSum, uint lockedMinSum) public {
        c.SetMinSum(newMinSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedMin;
        c.SetMinSum(lockedMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedMin = true;
        } else {
            revertedMin = false;
        }

        assert(revertedMin && c.MinSum() == newMinSum);
    }
}

