pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 newMinSum, uint256 lockedMinSum) internal {
        try c.SetMinSum(newMinSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool revertedMin;
        try c.SetMinSum(lockedMinSum) {
            revertedMin = false;
        } catch {
            revertedMin = true;
        }
        assertTrue(revertedMin && c.MinSum() == newMinSum);
    }

    function testFuzz_run(uint256 newMinSum, uint256 lockedMinSum) public {
        _run(newMinSum, lockedMinSum);
    }

    receive() external payable {}
}
